import {useMutation} from '@github-ui/react-query'
import {
  apiUpdateIssueIssueTypeBulk,
  type UpdateIssueIssueTypeBulkRequest,
} from '../api/api-update-issue-issue-type-bulk'
import {parseGraphQLResponse} from '@github-ui/item-picker-base/api/graphql'
import type {IssueType} from '../api/issue-type'

type UseUpdateIssueIssueTypeBulkMutationInput = UpdateIssueIssueTypeBulkRequest & {issueType?: IssueType}

type UseUpdateIssueIssueTypeBulkMutationOptions = {
  onMutate: (variables: UseUpdateIssueIssueTypeBulkMutationInput) => void
}

export function useUpdateIssueIssueTypeBulkMutation({onMutate}: UseUpdateIssueIssueTypeBulkMutationOptions) {
  return useMutation({
    mutationFn: async ({issueType, ...request}: UseUpdateIssueIssueTypeBulkMutationInput) => {
      const responseJson = await apiUpdateIssueIssueTypeBulk(request)
      const responseData = parseGraphQLResponse(responseJson)
      return responseData
    },
    onMutate,
  })
}
